<?php
/** Administrative layout, keeping destructive operations behind CSRF-protected forms. */
use yii\helpers\Html;
$action = Yii::$app->controller->action->id;
$nav = ['index'=>'总览','team'=>'团队信息','profile'=>'我的资料','projects'=>'项目管理','updates'=>'动态管理','messages'=>'留言管理','members'=>'成员管理'];
if (!Yii::$app->user->isGuest && !Yii::$app->user->identity->isAdmin()) {
    unset($nav['team'], $nav['messages'], $nav['members']);
}
$this->beginPage(); ?><!DOCTYPE html><html lang="zh-CN"><head><meta charset="<?= Yii::$app->charset ?>"><meta name="viewport" content="width=device-width,initial-scale=1"><?= Html::csrfMetaTags() ?><title><?= Html::encode($this->title ?: '星河工坊 · 工作台') ?></title><link rel="stylesheet" href="/assets/site.css"><?php $this->head() ?></head><body class="admin-body"><?php $this->beginBody() ?><a class="skip-link" href="#main">跳到主要内容</a><aside class="admin-sidebar"><a class="brand" href="/admin/"><span class="brand-mark">✳</span><span>星河工坊<small>STUDIO WORKSPACE</small></span></a><span class="sidebar-label">工作空间</span><nav aria-label="后台导航"><?php foreach ($nav as $id=>$label): ?><a <?= $action === $id || rtrim($action,'s') === rtrim($id,'s') ? 'class="active" aria-current="page"' : '' ?> href="/admin/?r=site/<?= $id ?>"><?= $label ?><span>↗</span></a><?php endforeach ?></nav><div class="sidebar-bottom"><a href="/">← 访问公开主页</a><?php if (!Yii::$app->user->isGuest): ?><?= Html::beginForm(['/site/logout'],'post') ?><?= Html::submitButton('退出登录',['class'=>'logout-button']) ?><?= Html::endForm() ?><?php endif ?></div></aside><div class="admin-workspace"><header class="admin-topbar"><span>工作台 <span class="muted">/ 让每次协作井井有条</span></span><span>✦ <?= Html::encode(Yii::$app->user->isGuest ? '访客' : Yii::$app->user->identity->username) ?></span></header><main id="main" class="admin-main"><?php foreach (Yii::$app->session->getAllFlashes() as $type=>$message): ?><div class="alert <?= Html::encode($type) ?>" role="status"><?= Html::encode(is_array($message) ? implode('；',$message) : $message) ?></div><?php endforeach ?><?= $content ?></main><footer class="admin-footer">星河工坊 · 保持好奇，认真构建。</footer></div><?php $this->endBody() ?></body></html><?php $this->endPage() ?>
